function validate([m, n]) {
  if (!Number.isInteger(m) || m < 1 || m > 5) return 'm must be a whole number from 1 to 5.';
  if (!Number.isInteger(n) || n < 1 || n > 1000) return 'n must be a whole number from 1 to 1000.';
