function colorTheGrid(m, n) {
  const MOD = 1e9 + 7;
  const columns = [];
  for (let mask = 0; mask < 3 ** m; mask++) {
    const colors = [];
    let rest = mask;
    for (let row = 0; row < m; row++) {
      colors.push(rest % 3);
      rest = Math.floor(rest / 3);
    }
    if (colors.every((color, row) => row === 0 || color !== colors[row - 1])) {
      columns.push(colors);
    }
  }
  const count = columns.length;
  const fits = columns.map(() => []);
  for (let i = 0; i < count; i++) {
    for (let j = 0; j < count; j++) {
      if (columns[i].every((color, row) => color !== columns[j][row])) {
        fits[i].push(j);
      }
    }
  }
  let dp = new Array(count).fill(1);
  for (let col = 1; col < n; col++) {
    const next = new Array(count).fill(0);
    for (let prev = 0; prev < count; prev++) {
      for (const cur of fits[prev]) {
        next[cur] = (next[cur] + dp[prev]) % MOD;
      }
    }
    dp = next;
  }
  return dp.reduce((total, ways) => (total + ways) % MOD, 0);
}

