function colorTheGrid(m, n) {
  // Fill the grid one cell at a time, column by column, remembering only the last m colors placed.
  const MOD = 1000000007;
  let states = new Map([['', 1]]);
  for (let cell = 0; cell < m * n; cell++) {
    const row = cell % m;
    const nextStates = new Map();
    for (const [key, ways] of states) {
      const recent = key === '' ? [] : key.split(',').map(Number);
      for (let color = 0; color < 3; color++) {
        if (row > 0 && recent[recent.length - 1] === color) continue;
        if (cell >= m && recent[recent.length - m] === color) continue;
        const kept = [...recent, color].slice(-m).join(',');
        nextStates.set(kept, ((nextStates.get(kept) || 0) + ways) % MOD);
      }
    }
    states = nextStates;
  }
  let total = 0;
  for (const ways of states.values()) total = (total + ways) % MOD;
  return total;
}

