function generate(rand, size) {
  if (size === 'large') {
    const m = 3 + Math.floor(rand() * 3);
    const n = 800 + Math.floor(rand() * 201);
    return [m, n];
  }
  const m = 1 + Math.floor(rand() * 5);
  const n = 1 + Math.floor(rand() * 9);
  return [m, n];
